s=>{
    Object.assign(s.uniforms,SURFACE);
    s.vertexShader=VERT_HEAD+'varying vec3 vWhT;\n'+(crate?'attribute vec3 warehouseCenter;attribute vec3 warehouseHalf;varying vec3 vWhA;varying vec3 vWhH;\n':'')+
      s.vertexShader.replace('#include <begin_vertex>',`#include <begin_vertex>
      ${VERT_POS}
      vWhT=${local?'mat3(modelMatrix)*whPos.xyz':'vWhP'};
      ${crate?'vWhA=warehouseCenter;vWhH=warehouseHalf;':''}`);
    const body=zoned?`
      vec3 wzInk,wzIvory,wzGround;float wzDeck;whZone(vWhP,wzInk,wzIvory,wzGround,wzDeck);
      if(whA.y>.6){
        whUV=vWhT.xz*${scale.toFixed(3)};vec3 c=texture2D(map,whUV).rgb*mix(.70,1.2,texture2D(uWhMacro,vWhT.xz*.027).r);
        vec2 g=vWhT.xz/6.,f=abs(fract(g)-.5);float w=fwidth(g.x)+fwidth(g.y);
        c*=.91+.18*whHash(floor(g));c*=1.-.55*smoothstep(.488-w,.494+w,max(f.x,f.y));
        c*=wzGround;if(whN.y<0.)c*=.42;diffuseColor.rgb=c;
      }else{
        float up=smoothstep(wzDeck+3.,wzDeck+3.04,vWhP.y);whSel=up>.5?2.:1.;whUV=whSide*(up>.5?.2:.25);
        vec3 c=mix(texture2D(uWhDado,whSide*.25).rgb*wzInk,texture2D(uWhClad,whSide*.2).rgb*wzIvory,up)*mix(.78,1.14,texture2D(uWhMacro,whSide*.041).r);
        c=mix(c,vec3(.80,.42,.11),1.-smoothstep(.05,.10,abs(vWhP.y-wzDeck-3.04)));
        c*=.56+.44*smoothstep(wzDeck,wzDeck+1.5,vWhP.y);diffuseColor.rgb=c;
      }`:crate?`
      vec3 whBox=floor(vWhA*2.+.5);float id=whHash(whBox.xz+whBox.y);whUV=(whA.y>.6?vWhT.xz:whSide)*${scale.toFixed(3)}+id*7.;
      vec3 tint=id<.25?vec3(.62,.21,.13):id<.5?vec3(.14,.40,.42):id<.75?vec3(.82,.56,.18):vec3(.20,.27,.44);
      vec3 c=texture2D(map,whUV).rgb*tint*1.5;
      if(vWhH.x>0.){vec3 l=abs(vWhP-vWhA);
        float e=whA.y>.6?min(vWhH.x-l.x,vWhH.z-l.z):whA.x>whA.z?min(vWhH.z-l.z,vWhH.y-l.y):min(vWhH.x-l.x,vWhH.y-l.y);
        c=mix(c,vec3(.13,.14,.15)*texture2D(map,whUV*2.).r*2.,1.-smoothstep(.10,.125,e));
        c=mix(c,vec3(.62,.60,.54),(1.-smoothstep(.012,.04,e))*.8);
        if(whA.y<=.6)c*=.58+.42*smoothstep(0.,.55,vWhP.y-vWhA.y+vWhH.y);
      }
      diffuseColor.rgb=c;`:`
      whUV=(whA.y>.6?vWhT.xz:whSide)*${scale.toFixed(3)};
      diffuseColor.rgb*=texture2D(map,whUV).rgb*mix(.82,1.14,texture2D(uWhMacro,whUV*.13).r);`;
    s.fragmentShader=FRAG_HEAD+'varying vec3 vWhT;\nuniform sampler2D uWhMacro,uWhDado,uWhDadoN,uWhClad,uWhCladN;\n'+(crate?'varying vec3 vWhA;varying vec3 vWhH;\n':'')+HASH+ZONE+s.fragmentShader
      .replace('#include <map_fragment>',`vec3 whN=normalize(cross(dFdx(vWhP),dFdy(vWhP))),whA=abs(whN);
      vec2 whSide=whA.x>whA.z?vWhT.zy:vWhT.xy,whUV=whSide;float whSel=0.;${body}`)
      .replace('#include <normal_fragment_begin>',T.ShaderChunk.normal_fragment_begin.replaceAll('vNormalMapUv','whUV'))
      .replace('#include <normal_fragment_maps>',normal?`{vec3 mapN=(whSel>1.5?texture2D(uWhCladN,whUV):whSel>.5?texture2D(uWhDadoN,whUV):texture2D(normalMap,whUV)).xyz*2.-1.;
        mapN.xy*=normalScale;normal=normalize(tbn*mapN);}`:'')
      .replace('#include <lights_fragment_end>',FRAG_LIGHT);
  }

